import '../css/mainPage.css';

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

import logo from "../image/tybwhitelogo.png";
import logoblack from "../image/tyblogoblack.jpeg";
import esign1 from "../image/georgeEsign.jpeg";

import DashboardIcon from "@mui/icons-material/Dashboard";
import PrintIcon from "@mui/icons-material/Print";

const units = ["kg", "gms", "pcs"];

const productForCustomers = [
    "Filter Coffee",
    "Instant Coffee",
    "Coffee Bean",
    "Pepper",
    "Honey",
    "Small combo",
    "Medium combo",
    "Big combo"
];

const msme = process.env.REACT_APP_MSME;

const API_URL = "http://localhost:5000/api";

function MainPage() {

    // =========================================================
    // RESORT BILLING
    // =========================================================

    const [customer, setCustomer] = useState("");
    const [product, setProduct] = useState("");
    const [quantity, setQuantity] = useState(1);

    const [resortCustomers, setResortCustomers] = useState([]);
    const [resortProducts, setResortProducts] = useState([]);

    const [cart, setCart] = useState([]);

    const [billNo, setBillNo] = useState(1);
    const [isManual, setIsManual] = useState(false);
    const [selectedDate, setSelectedDate] = useState("");
    const [balance, setBalance] = useState();

    // Used to prevent creating the same order multiple times
    const [orderSaved, setOrderSaved] = useState(false);
    const [savingOrder, setSavingOrder] = useState(false);

    // =========================================================
    // ONLY FOR CUSTOMERS
    // =========================================================

    const [cust, setCust] = useState("");
    const [addr, setAddr] = useState("");
    const [custProduct, setCustProduct] = useState("");
    const [custQuanity, setCustQuantity] = useState("");
    const [custunit, setCustUnit] = useState("");
    const [customerPrice, setCustomerPrice] = useState();
    const [customerCart, setCustomerCart] = useState([]);

    // =========================================================
    // FETCH RESORT CUSTOMERS
    // =========================================================

    useEffect(() => {

        const fetchResortCustomers = async () => {

            try {

                const response = await fetch(
                    `${API_URL}/resort-customers`
                );

                if (!response.ok) {
                    throw new Error(
                        "Failed to fetch resort customers"
                    );
                }

                const data = await response.json();

                setResortCustomers(data);

            } catch (error) {

                console.error(
                    "Error fetching resort customers:",
                    error
                );

            }
        };

        fetchResortCustomers();

    }, []);

    // =========================================================
    // FETCH PRODUCTS + COMBOS FOR SELECTED RESORT CUSTOMER
    // =========================================================

    const handleResortCustomerChange = async (e) => {

        const customerId = e.target.value;

        setCustomer(customerId);

        // Reset selected product
        setProduct("");

        // Clear previously loaded products
        setResortProducts([]);

        // Reset order state because customer changed
        setOrderSaved(false);

        if (!customerId) {
            return;
        }

        try {

            const response = await fetch(
                `${API_URL}/resort-customers/${customerId}/products`
            );

            if (!response.ok) {
                throw new Error(
                    "Failed to fetch products for resort customer"
                );
            }

            const data = await response.json();

            setResortProducts(data);

        } catch (error) {

            console.error(
                "Error fetching resort products:",
                error
            );

        }
    };

    // =========================================================
    // SELECTED PRODUCT / COMBO
    // =========================================================

    /*
        Product dropdown value:

        product-<product_variant_id>

        OR

        combo-<combo_id>

        Example:

        product-5
        combo-2
    */

    const selectedResortProduct = resortProducts.find(
        (item) => {

            if (!product) {
                return false;
            }

            // Product
            if (
                item.product_variant_id !== null &&
                item.product_variant_id !== undefined
            ) {

                return (
                    product ===
                    `product-${item.product_variant_id}`
                );

            }

            // Combo
            if (
                item.combo_id !== null &&
                item.combo_id !== undefined
            ) {

                return (
                    product ===
                    `combo-${item.combo_id}`
                );

            }

            return false;
        }
    );

    // =========================================================
    // PRICE
    // =========================================================

    const price =
        Number(selectedResortProduct?.price) || 0;

    const totalPrice =
        price * Number(quantity || 0);

    // =========================================================
    // ADD RESORT ITEM TO CART
    // =========================================================

    const handleAdd = () => {

        if (
            !customer ||
            !product ||
            !selectedResortProduct ||
            Number(quantity) <= 0
        ) {
            alert("Please select customer, product and quantity.");
            return;
        }

        const selectedCustomer =
            resortCustomers.find(
                (c) =>
                    Number(c.resort_customer_id) ===
                    Number(customer)
            );

        const isCombo =
            selectedResortProduct.combo_id !== null &&
            selectedResortProduct.combo_id !== undefined;

        const newItem = {

            id: Date.now(),

            customer:
                selectedCustomer?.customer_name || "",

            customerId:
                Number(customer),

            address:
                selectedCustomer?.address || "",

            // product or combo
            type:
                isCombo ? "combo" : "product",

            // Display name
            product:
                isCombo
                    ? selectedResortProduct.combo_name
                    : selectedResortProduct.product_name,

            // Database IDs
            productVariantId:
                isCombo
                    ? null
                    : selectedResortProduct.product_variant_id,

            comboId:
                isCombo
                    ? selectedResortProduct.combo_id
                    : null,

            // Product pack size
            packSize:
                isCombo
                    ? null
                    : selectedResortProduct.pack_size_grams,

            quantity:
                Number(quantity),

            price:
                Number(price),

            total:
                Number(totalPrice)
        };

        setCart([
            ...cart,
            newItem
        ]);

        // Since cart changed, a new order needs to be saved
        setOrderSaved(false);

        // Reset product and quantity
        setProduct("");
        setQuantity(1);
    };

    // =========================================================
    // DELETE RESORT ITEM
    // =========================================================

    const handleDelete = (id) => {

        setCart(
            cart.filter(
                (item) => item.id !== id
            )
        );

        // Order needs to be recreated after modifying cart
        setOrderSaved(false);
    };

    // =========================================================
    // CUSTOMER TOTAL
    // =========================================================

    let custTotalPrice;

    if (custunit === "gms") {

        custTotalPrice =
            (custQuanity / 1000) *
            customerPrice;

    } else {

        custTotalPrice =
            customerPrice *
            custQuanity;
    }

    // =========================================================
    // ADD NORMAL CUSTOMER ITEM
    // =========================================================

    const handleAddCustomer = () => {

        if (
            !cust ||
            !custProduct ||
            custQuanity <= 0
        ) {
            return;
        }

        const cartItem = {

            id: Date.now(),

            cust,

            addr,

            custProduct,

            custQuanity,

            custunit,

            customerPrice,

            custtotal:
                custTotalPrice
        };

        setCustomerCart([
            ...customerCart,
            cartItem
        ]);

        // Reset inputs
        setCustProduct("");
        setCustQuantity(1);
    };

    // =========================================================
    // DELETE NORMAL CUSTOMER ITEM
    // =========================================================

    const handleDeleteForCustomers = (id) => {

        setCustomerCart(
            customerCart.filter(
                (item) => item.id !== id
            )
        );
    };

    // =========================================================
    // GRAND TOTAL
    // =========================================================

    let grandTotal;
    let balSNo;

    if (balance) {

        grandTotal =
            cart.reduce(
                (sum, item) =>
                    sum + item.total,
                0
            );

        grandTotal += Number(balance);

        balSNo =
            cart.length + 1;

    } else if (cart.length !== 0) {

        grandTotal =
            cart.reduce(
                (sum, item) =>
                    sum + item.total,
                0
            );

    } else {

        grandTotal =
            customerCart.reduce(
                (sum, item) =>
                    sum + item.custtotal,
                0
            );
    }

    // =========================================================
    // CREATE ORDER IN BACKEND
    // =========================================================

    const saveResortOrder = async () => {

        // We only create an order for resort billing
        if (!customer) {
            return true;
        }

        // No cart items means nothing to save
        if (cart.length === 0) {
            alert("Please add at least one item.");
            return false;
        }

        // Prevent duplicate order creation
        if (orderSaved) {
            return true;
        }

        if (savingOrder) {
            return false;
        }

        setSavingOrder(true);

        try {

            /*
                Convert frontend cart into the structure
                expected by the backend.

                Backend expects:

                {
                    productVariantId,
                    comboId,
                    quantity,
                    price
                }
            */

            const items = cart.map((item) => ({

                productVariantId:
                    item.productVariantId || null,

                comboId:
                    item.comboId || null,

                quantity:
                    Number(item.quantity),

                price:
                    Number(item.price)

            }));

            const response = await fetch(
                `${API_URL}/resort-customers/${customer}/orders`,
                {
                    method: "POST",

                    headers: {
                        "Content-Type": "application/json"
                    },

                    body: JSON.stringify({

                        orderDate:
                            selectedDate,

                        totalAmount:
                            Number(grandTotal),

                        items:
                            items

                    })
                }
            );

            const data = await response.json();

            if (!response.ok) {

                throw new Error(
                    data.message ||
                    "Failed to create order"
                );
            }

            console.log(
                "Order created successfully:",
                data
            );

            setOrderSaved(true);

            return true;

        } catch (error) {

            console.error(
                "Error creating resort order:",
                error
            );

            alert(
                "Failed to save order. Bill was not printed."
            );

            return false;

        } finally {

            setSavingOrder(false);
        }
    };

    // =========================================================
    // NUMBER TO WORDS
    // =========================================================

    function numberToWords(num) {

        const ones = [
            "",
            "One",
            "Two",
            "Three",
            "Four",
            "Five",
            "Six",
            "Seven",
            "Eight",
            "Nine",
            "Ten",
            "Eleven",
            "Twelve",
            "Thirteen",
            "Fourteen",
            "Fifteen",
            "Sixteen",
            "Seventeen",
            "Eighteen",
            "Nineteen"
        ];

        const tens = [
            "",
            "",
            "Twenty",
            "Thirty",
            "Forty",
            "Fifty",
            "Sixty",
            "Seventy",
            "Eighty",
            "Ninety"
        ];

        function convert(n) {

            if (n < 20) {
                return ones[n];
            }

            if (n < 100) {

                return (
                    tens[Math.floor(n / 10)] +
                    " " +
                    ones[n % 10]
                );
            }

            if (n < 1000) {

                return (
                    ones[Math.floor(n / 100)] +
                    " Hundred " +
                    convert(n % 100)
                );
            }

            if (n < 100000) {

                return (
                    convert(
                        Math.floor(n / 1000)
                    ) +
                    " Thousand " +
                    convert(n % 1000)
                );
            }

            if (n < 10000000) {

                return (
                    convert(
                        Math.floor(n / 100000)
                    ) +
                    " Lakh " +
                    convert(n % 100000)
                );
            }

            return (
                convert(
                    Math.floor(n / 10000000)
                ) +
                " Crore " +
                convert(n % 10000000)
            );
        }

        return convert(
            Math.floor(num)
        ) + " Only";
    }

    // =========================================================
    // PRINT
    // =========================================================

    const handlePrint = async () => {

        /*
            For resort billing:
            Save order first, then print.
        */

        if (customer) {

            const saved =
                await saveResortOrder();

            if (!saved) {
                return;
            }
        }

        window.print();
    };

    // =========================================================
    // DATE
    // =========================================================

    const currentDate = new Date();

    const date =
        currentDate
            .toISOString()
            .split("T")[0];

    useEffect(() => {

        if (!isManual) {
            setSelectedDate(date);
        }

    }, [isManual, date]);

    // =========================================================
    // FORMAT DATE
    // =========================================================

    const formatDate = (dateStr) => {

        if (!dateStr) {
            return "";
        }

        const [
            year,
            month,
            day
        ] = dateStr.split("-");

        return `${day}/${month}/${year}`;
    };

    // =========================================================
    // NAVIGATION
    // =========================================================

    const navigate = useNavigate();

    // =========================================================
    // SELECTED RESORT CUSTOMER
    // =========================================================

    const selectedResortCustomer =
        resortCustomers.find(
            (c) =>
                Number(c.resort_customer_id) ===
                Number(customer)
        );

    // =========================================================
    // UI
    // =========================================================

    return (

        <div className="maindiv">

            {/* =====================================================
                HEADER
            ===================================================== */}

            <div className="header">

                <div>

                    <img
                        src={logo}
                        alt="logo"
                    />

                    <br />

                    <span
                        style={{
                            color: "white",
                            paddingLeft: "20px"
                        }}
                    >
                        The Yercaud Bean
                    </span>

                </div>

                <div>

                    <button
                        onClick={() =>
                            navigate("/dashboard")
                        }
                    >
                        <DashboardIcon />
                    </button>

                    <button
                        onClick={() =>
                            navigate("/courier")
                        }
                    >
                        <PrintIcon />
                    </button>

                </div>

            </div>

            <div className="mainbody">

                <h2>Credit Bill</h2>

                {/* =====================================================
                    DATE AND BILL NUMBER
                ===================================================== */}

                <div className="selectDateandBillNo">

                    <div>

                        <input
                            type="date"
                            style={{
                                marginRight: "10px",
                                paddingTop: "3px",
                                paddingBottom: "3px"
                            }}
                            value={selectedDate}
                            onChange={(e) =>
                                setSelectedDate(
                                    e.target.value
                                )
                            }
                            disabled={!isManual}
                        />

                        <button
                            onClick={() =>
                                setIsManual(
                                    !isManual
                                )
                            }
                        >
                            {isManual
                                ? "Today"
                                : "Custom"}
                        </button>

                    </div>

                    <div>

                        <input
                            type="number"
                            placeholder="Bill No"
                            onChange={(e) =>
                                setBillNo(
                                    Number(
                                        e.target.value
                                    )
                                )
                            }
                            style={{
                                marginRight: "10px",
                                marginBottom: "10px",
                                paddingTop: "3px",
                                paddingBottom: "3px",
                                border: "2px solid black",
                                borderRadius: "5px",
                                paddingLeft: "5px"
                            }}
                        />

                    </div>

                </div>

                {/* =====================================================
                    RESORT BILLING
                ===================================================== */}

                <div className="inputDetails">

                    {/* CUSTOMER */}

                    <select
                        style={{
                            width: "300px",
                            border: "2px solid black",
                            borderRadius: "5px",
                            paddingTop: "10px",
                            paddingBottom: "10px",
                            paddingLeft: "5px"
                        }}
                        value={customer}
                        onChange={
                            handleResortCustomerChange
                        }
                    >

                        <option value="">
                            Select customer
                        </option>

                        {resortCustomers.map(
                            (c) => (

                                <option
                                    key={
                                        c.resort_customer_id
                                    }
                                    value={
                                        c.resort_customer_id
                                    }
                                >
                                    {
                                        c.customer_name
                                    }
                                </option>

                            )
                        )}

                    </select>

                    {/* PRODUCT / COMBO */}

                    <select
                        style={{
                            width: "300px",
                            border: "2px solid black",
                            borderRadius: "5px",
                            paddingTop: "10px",
                            paddingBottom: "10px",
                            paddingLeft: "5px"
                        }}
                        value={product}
                        onChange={(e) =>
                            setProduct(
                                e.target.value
                            )
                        }
                        disabled={!customer}
                    >

                        <option value="">
                            Select product
                        </option>

                        {resortProducts.map(
                            (p) => {

                                const isCombo =
                                    p.combo_id !== null &&
                                    p.combo_id !== undefined;

                                const value =
                                    isCombo
                                        ? `combo-${p.combo_id}`
                                        : `product-${p.product_variant_id}`;

                                return (

                                    <option
                                        key={value}
                                        value={value}
                                    >

                                        {isCombo
                                            ? p.combo_name
                                            : `${p.product_name} - ${p.pack_size_grams}g`
                                        }

                                    </option>
                                );
                            }
                        )}

                    </select>

                    {/* QUANTITY */}

                    <input
                        style={{
                            width: "290px",
                            border: "2px solid black",
                            borderRadius: "5px",
                            paddingTop: "10px",
                            paddingBottom: "10px",
                            paddingLeft: "5px"
                        }}
                        type="number"
                        placeholder="Enter quantity"
                        value={quantity}
                        min="1"
                        onChange={(e) =>
                            setQuantity(
                                Number(
                                    e.target.value
                                )
                            )
                        }
                    />

                    {/* PRICE */}

                    <input
                        style={{
                            width: "290px",
                            border: "2px solid black",
                            borderRadius: "5px",
                            paddingTop: "10px",
                            paddingBottom: "10px",
                            paddingLeft: "5px"
                        }}
                        type="text"
                        value={
                            price
                                ? `₹${price}`
                                : ""
                        }
                        readOnly
                        placeholder="Price"
                    />

                    {/* TOTAL PRICE */}

                    <input
                        style={{
                            width: "290px",
                            border: "2px solid black",
                            borderRadius: "5px",
                            paddingTop: "10px",
                            paddingBottom: "10px",
                            paddingLeft: "5px"
                        }}
                        type="text"
                        value={
                            totalPrice
                                ? `₹${totalPrice}`
                                : ""
                        }
                        readOnly
                        placeholder="Total price"
                    />

                    {/* ADD */}

                    <button
                        onClick={handleAdd}
                    >
                        Add
                    </button>

                </div>

                {/* BALANCE */}

                <input
                    onChange={(e) =>
                        setBalance(
                            Number(
                                e.target.value
                            )
                        )
                    }
                    style={{
                        width: "290px",
                        border: "2px solid black",
                        borderRadius: "5px",
                        paddingTop: "10px",
                        paddingBottom: "10px",
                        paddingLeft: "5px"
                    }}
                    type="text"
                    placeholder="Balance"
                />

                {/* =====================================================
                    ONLY FOR CUSTOMERS
                ===================================================== */}

                <h2>Only for customers</h2>

                <div className="inputDetailsForCustomers">

                    <input
                        className="customerName"
                        type="text"
                        placeholder="Enter Name"
                        value={cust}
                        onChange={(e) =>
                            setCust(
                                e.target.value
                            )
                        }
                    />

                    <input
                        className="customerAddr"
                        type="text"
                        placeholder="Enter Address"
                        value={addr}
                        onChange={(e) =>
                            setAddr(
                                e.target.value
                            )
                        }
                    />

                    <select
                        value={custProduct}
                        onChange={(e) =>
                            setCustProduct(
                                e.target.value
                            )
                        }
                    >

                        <option value="">
                            Select product
                        </option>

                        {productForCustomers.map(
                            (p) => (

                                <option
                                    key={p}
                                    value={p}
                                >
                                    {p}
                                </option>

                            )
                        )}

                    </select>

                    <input
                        className="customerQuantity"
                        type="number"
                        placeholder="Enter Quantity"
                        value={custQuanity}
                        min="1"
                        onChange={(e) =>
                            setCustQuantity(
                                Number(
                                    e.target.value
                                )
                            )
                        }
                    />

                    <select
                        value={custunit}
                        onChange={(e) =>
                            setCustUnit(
                                e.target.value
                            )
                        }
                    >

                        <option value="">
                            Select Unit
                        </option>

                        {units.map(
                            (p) => (

                                <option
                                    key={p}
                                    value={p}
                                >
                                    {p}
                                </option>

                            )
                        )}

                    </select>

                    <br />

                    <span
                        style={{
                            color: "red"
                        }}
                    >
                        Enter per kg price if you
                        are choosing gms/kg.
                    </span>

                    <br />
                    <br />

                    <input
                        placeholder="Enter Price"
                        type="text"
                        value={customerPrice}
                        onChange={(e) =>
                            setCustomerPrice(
                                Number(
                                    e.target.value
                                )
                            )
                        }
                    />

                    <input
                        type="text"
                        value={
                            custTotalPrice
                                ? `${custTotalPrice}`
                                : ""
                        }
                        readOnly
                        placeholder="Total price"
                    />

                    <br />

                    <button
                        onClick={
                            handleAddCustomer
                        }
                    >
                        Add
                    </button>

                </div>

                {/* =====================================================
                    RESORT CART
                ===================================================== */}

                <h3
                    style={{
                        fontFamily:
                            "'Times New Roman', Times, serif"
                    }}
                >
                    Items purchased
                </h3>

                {cart.length === 0 ? (

                    <p
                        style={{
                            color: "grey",
                            fontFamily: "monospace",
                            fontSize: "15px"
                        }}
                    >
                        No items added
                    </p>

                ) : (

                    <table
                        className="itemDisplayTable"
                    >

                        <thead>

                            <tr>

                                <th>
                                    Customer
                                </th>

                                <th>
                                    Product
                                </th>

                                <th>
                                    Qty
                                </th>

                                <th>
                                    Price
                                </th>

                                <th>
                                    Total
                                </th>

                                <th>
                                    Action
                                </th>

                            </tr>

                        </thead>

                        <tbody>

                            {cart.map(
                                (item) => (

                                    <tr
                                        key={
                                            item.id
                                        }
                                    >

                                        <td>
                                            {
                                                item.customer
                                            }
                                        </td>

                                        <td>

                                            {
                                                item.product
                                            }

                                            {item.packSize
                                                ? ` (${item.packSize}g)`
                                                : ""
                                            }

                                        </td>

                                        <td>
                                            {
                                                item.quantity
                                            }
                                        </td>

                                        <td>
                                            ₹
                                            {
                                                item.price
                                            }
                                        </td>

                                        <td>
                                            ₹
                                            {
                                                item.total
                                            }
                                        </td>

                                        <td>

                                            <button
                                                onClick={() =>
                                                    handleDelete(
                                                        item.id
                                                    )
                                                }
                                            >
                                                Delete
                                            </button>

                                        </td>

                                    </tr>

                                )
                            )}

                        </tbody>

                    </table>
                )}

                {/* =====================================================
                    CUSTOMER CART
                ===================================================== */}

                {customerCart.length === 0 ? (

                    <p
                        style={{
                            color: "grey",
                            fontFamily: "monospace",
                            fontSize: "15px"
                        }}
                    >
                        No customer items added
                    </p>

                ) : (

                    <table
                        className="itemDisplayTable"
                    >

                        <thead>

                            <tr>

                                <th>
                                    Customer
                                </th>

                                <th>
                                    Product
                                </th>

                                <th>
                                    Qty
                                </th>

                                <th>
                                    Unit Price
                                </th>

                                <th>
                                    Total
                                </th>

                                <th>
                                    Action
                                </th>

                            </tr>

                        </thead>

                        <tbody>

                            {customerCart.map(
                                (item) => (

                                    <tr
                                        key={
                                            item.id
                                        }
                                    >

                                        <td>
                                            {
                                                item.cust
                                            }
                                        </td>

                                        <td>
                                            {
                                                item.custProduct
                                            }
                                        </td>

                                        <td>
                                            {
                                                item.custQuanity +
                                                item.custunit
                                            }
                                        </td>

                                        <td>
                                            ₹
                                            {
                                                item.customerPrice
                                            }
                                        </td>

                                        <td>
                                            ₹
                                            {
                                                item.custtotal
                                            }
                                        </td>

                                        <td>

                                            <button
                                                onClick={() =>
                                                    handleDeleteForCustomers(
                                                        item.id
                                                    )
                                                }
                                            >
                                                Delete
                                            </button>

                                        </td>

                                    </tr>

                                )
                            )}

                        </tbody>

                    </table>
                )}

                {/* =====================================================
                    GRAND TOTAL
                ===================================================== */}

                <h2>
                    Total: ₹{grandTotal}
                </h2>

                {/* =====================================================
                    PRINT
                ===================================================== */}

                <button
                    onClick={handlePrint}
                    disabled={savingOrder}
                    style={{
                        position: "relative",
                        zIndex: "10000"
                    }}
                >
                    {savingOrder
                        ? "Saving..."
                        : "Print"}
                </button>

                {/* =====================================================
                    PRINT BILL
                ===================================================== */}

                <div className="printBill">

                    <div className="billHeader">
                        Credit Bill
                    </div>

                    <div className="ownerDetails">

                        <div className="ownerDetailsLeft">

                            <span>
                                {msme}
                            </span>

                            <br />

                        </div>

                        <div className="ownerDetailsRight">

                            <img
                                src={logoblack}
                                style={{
                                    width: "50px"
                                }}
                                alt="logo"
                            />

                            <br />

                            <span
                                style={{
                                    fontSize: "15px"
                                }}
                            >
                                The Yercaud Bean
                            </span>

                            <br />

                            <span>
                                Lady's seat Rd,
                            </span>

                            <br />

                            <span>
                                Yercaud.
                            </span>

                            <br />

                            9994797824
                            <br />
                            8489333469

                        </div>

                    </div>

                    {/* CUSTOMER DETAILS */}

                    <div className="customerDetails">

                        <div className="toAddr">

                            <span
                                style={{
                                    fontWeight: "bold"
                                }}
                            >
                                BILL NO:
                            </span>

                            {" "}

                            {billNo}

                            <br />

                            <span
                                style={{
                                    fontWeight: "bold"
                                }}
                            >
                                BILLING TO:
                            </span>

                            <br />

                            {
                                cust
                                    ? cust
                                    : selectedResortCustomer?.customer_name ||
                                      ""
                            }

                            {(
                                cust
                                    ? cust
                                    : selectedResortCustomer?.customer_name ||
                                      ""
                            ) !== "Customer"
                                ? ","
                                : "."}

                            <br />

                            {
                                addr
                                    ? addr
                                    : selectedResortCustomer?.address ||
                                      ""
                            }

                            .

                        </div>

                        <div className="toDate">

                            <span
                                style={{
                                    fontWeight: "bold"
                                }}
                            >
                                BILLING DATE:
                            </span>

                            <br />

                            {formatDate(
                                selectedDate
                            )}

                        </div>

                    </div>

                    {/* BILL ITEMS */}

                    <table className="itemTable">

                        <tbody>

                            <tr
                                className="itemDisplayHeader"
                            >

                                <td
                                    style={{
                                        width: "50px"
                                    }}
                                >
                                    S No.
                                </td>

                                <td>
                                    Description
                                </td>

                                <td
                                    style={{
                                        width: "90px"
                                    }}
                                >
                                    Quantity
                                </td>

                                <td
                                    style={{
                                        width: "90px"
                                    }}
                                >
                                    Unit Price
                                </td>

                                <td
                                    style={{
                                        width: "90px"
                                    }}
                                >
                                    Total Price
                                </td>

                            </tr>

                            {/* RESORT ITEMS */}

                            {cart.map(
                                (item, index) => (

                                    <tr
                                        key={
                                            item.id
                                        }
                                        className="itemDisplay"
                                    >

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            {index + 1}
                                        </td>

                                        <td
                                            style={{
                                                paddingLeft:
                                                    "5px"
                                            }}
                                        >

                                            {
                                                item.product
                                            }

                                            {item.packSize
                                                ? ` (${item.packSize}g)`
                                                : ""
                                            }

                                        </td>

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            {
                                                item.quantity
                                            }
                                        </td>

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            ₹
                                            {
                                                item.price
                                            }
                                        </td>

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            ₹
                                            {
                                                item.total
                                            }
                                        </td>

                                    </tr>

                                )
                            )}

                            {/* CUSTOMER ITEMS */}

                            {customerCart.map(
                                (item, index) => (

                                    <tr
                                        key={
                                            item.id
                                        }
                                        className="itemDisplay"
                                    >

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            {cart.length +
                                                index +
                                                1}
                                        </td>

                                        <td
                                            style={{
                                                paddingLeft:
                                                    "5px"
                                            }}
                                        >
                                            {
                                                item.custProduct
                                            }
                                        </td>

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            {
                                                item.custQuanity +
                                                item.custunit
                                            }
                                        </td>

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            ₹
                                            {
                                                item.customerPrice
                                            }
                                        </td>

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            ₹
                                            {
                                                item.custtotal
                                            }
                                        </td>

                                    </tr>

                                )
                            )}

                            {/* BALANCE */}

                            {balance > 0 && (

                                <tr>

                                    <td
                                        style={{
                                            textAlign:
                                                "center"
                                        }}
                                    >
                                        {
                                            cart.length +
                                            customerCart.length +
                                            1
                                        }
                                    </td>

                                    <td
                                        style={{
                                            paddingLeft:
                                                "5px"
                                        }}
                                    >
                                        Balance
                                    </td>

                                    <td
                                        style={{
                                            textAlign:
                                                "center"
                                        }}
                                        colSpan={2}
                                    >
                                        ₹{balance}
                                    </td>

                                    <td
                                        style={{
                                            textAlign:
                                                "center"
                                        }}
                                    >
                                        ₹{balance}
                                    </td>

                                </tr>

                            )}

                        </tbody>

                    </table>

                    {/* AMOUNT */}

                    <table className="amtTable">

                        <tbody>

                            <tr>

                                <td
                                    style={{
                                        paddingLeft:
                                            "5px"
                                    }}
                                >

                                    <span
                                        style={{
                                            fontWeight:
                                                "bold"
                                        }}
                                    >
                                        Amount in words:
                                    </span>

                                    {" "}

                                    {numberToWords(
                                        grandTotal
                                    )}

                                </td>

                                <td
                                    style={{
                                        width: "90px",
                                        textAlign:
                                            "center",
                                        borderRight:
                                            "1px white solid",
                                        fontWeight:
                                            "bold"
                                    }}
                                >
                                    Grand Total
                                </td>

                                <td
                                    style={{
                                        width: "90px",
                                        textAlign:
                                            "center"
                                    }}
                                >
                                    {grandTotal}
                                </td>

                            </tr>

                        </tbody>

                    </table>

                    {/* FOOTER */}

                    <div className="footer">

                        <div className="terms">

                            <span
                                style={{
                                    fontWeight:
                                        "bold"
                                }}
                            >
                                Terms & Condition
                                <sup>*</sup>
                            </span>

                            <br />

                            Payment must be paid within
                            15 days from the issue of bill.

                        </div>

                        <div className="signature">

                            <img
                                src={esign1}
                                style={{
                                    width: "70px",
                                    marginLeft: "350px"
                                }}
                                alt="signature"
                            />

                            <br />

                            Signature

                        </div>

                    </div>

                </div>

            </div>

        </div>
    );
}

export default MainPage;
